module exploding_worms (\n    input wire clk,\n    input wire rst_n,\n    input wire start,\n    input wire [2:0] shoot_index,\n    input wire [7:0] pos0, pos1, pos2, pos3, pos4, pos5, pos6, pos7,\n    input wire [7:0] rad0, rad1, rad2, rad3, rad4, rad5, rad6, rad7,\n    output reg [3:0] result,\n    output reg done\n);\n\n// State definitions\nlocalparam [2:0] IDLE       = 3'd0;\nlocalparam [2:0] INIT       = 3'd1;\nlocalparam [2:0] EXPAND_I   = 3'd2;\nlocalparam [2:0] EXPAND_J   = 3'd3;\nlocalparam [2:0] CHECK      = 3'd4;\nlocalparam [2:0] COUNT      = 3'd5;\nlocalparam [2:0] DONE_STATE = 3'd6;\n\n// Internal registers\nreg [2:0] state;\nreg [7:0] mask;\nreg [7:0] new_mask;\nreg [2:0] i;\nreg [2:0] j;\nreg [2:0] iteration_count;\n\n// Position and radius arrays\nwire signed [7:0] pos [0:7];\nwire [7:0] rad [0:7];\n\nassign pos[0] = pos0;\nassign pos[1] = pos1;\nassign pos[2] = pos2;\nassign pos[3] = pos3;\nassign pos[4] = pos4;\nassign pos[5] = pos5;\nassign pos[6] = pos6;\nassign pos[7] = pos7;\n\nassign rad[0] = rad0;\nassign rad[1] = rad1;\nassign rad[2] = rad2;\nassign rad[3] = rad3;\nassign rad[4] = rad4;\nassign rad[5] = rad5;\nassign rad[6] = rad6;\nassign rad[7] = rad7;\n\n// Absolute difference calculation\nwire signed [8:0] diff;\nwire [7:0] abs_diff;\nassign diff = $signed(pos[i]) - $signed(pos[j]);\nassign abs_diff = diff[8] ? (~diff[7:0] + 1'b1) : diff[7:0];\n\n// Popcount combinatorial logic\nwire [3:0] popcount;\nassign popcount = \
    mask[0] + mask[1] + mask[2] + mask[3] + \
    mask[4] + mask[5] + mask[6] + mask[7];\n\n// State machine\nalways @(posedge clk or negedge rst_n) begin\n    if (!rst_n) begin\n        state <= IDLE;\n        mask <= 8'd0;\n        new_mask <= 8'd0;\n        i <= 3'd0;\n        j <= 3'd0;\n        iteration_count <= 3'd0;\n        result <= 4'd0;\n        done <= 1'b0;\n    end else begin\n        case (state)\n            IDLE: begin\n                done <= 1'b0;\n                if (start) state <= INIT;\n            end\n            \n            INIT: begin\n                mask <= 8'd0;\n                new_mask <= 8'd0;\n                mask[shoot_index] <= 1'b1;\n                new_mask[shoot_index] <= 1'b1;\n                iteration_count <= 3'd0;\n                state <= EXPAND_I;\n            end\n            \n            EXPAND_I: begin\n                if (i >= 3'd7) begin\n                    i <= 3'd0;\n                    state <= CHECK;\n                end else begin\n                    if (mask[i]) begin\n                        j <= 3'd0;\n                        state <= EXPAND_J;\n                    end else begin\n                        i <= i + 3'd1;\n                        state <= EXPAND_I;\n                    end\n                end\n            end\n            \n            EXPAND_J: begin\n                if (j >= 3'd7) begin\n                    i <= i + 3'd1;\n                    state <= EXPAND_I;\n                end else begin\n                    if (!mask[j]) begin\n                        if (abs_diff <= rad[i]) begin\n                            new_mask[j] <= 1'b1;\n                        end\n                    end\n                    j <= j + 3'd1;\n                end\n            end\n            \n            CHECK: begin\n                if ((new_mask == mask) || (iteration_count >= 3'd7)) begin\n                    state <= COUNT;\n                end else begin\n                    mask <= new_mask;\n                    iteration_count <= iteration_count + 3'd1;\n                    i <= 3'd0;\n                    state <= EXPAND_I;\n                end\n            end\n            \n            COUNT: begin\n                result <= popcount;\n                state <= DONE_STATE;\n            end\n            \n            DONE_STATE: begin\n                done <= 1'b1;\n                if (!start) state <= IDLE;\n            end\n            \n            default: state <= IDLE;\n        endcase\n    end\nend\n\nendmodule